import os, json, time, subprocess, statistics, hashlib, platform
from pathlib import Path
ROOT=Path('/opt/sevenz-input')
os.chdir(ROOT)
def sample(arm,threads,fixture):
 out=ROOT/'out.7z'
 out.unlink(missing_ok=True)
 if arm=='7zz':
  args=[str(ROOT/'sevenzip/7zz'),'a','-t7z','-mx5',f'-mmt={threads}','-m0=lzma2:d=32m',str(out),'data.bin']
 else:
  args=[str(ROOT/arm),'op','encode','--input',str(ROOT/fixture),'--out',str(out),'--level','5','--threads',str(threads)]
 with open(ROOT/'child.log','wb') as log:
  start=time.perf_counter_ns()
  p=subprocess.Popen(args,cwd=ROOT/fixture,stdout=log,stderr=subprocess.STDOUT)
  _,status,r=os.wait4(p.pid,0)
  wall=(time.perf_counter_ns()-start)/1e9
  p.returncode=os.waitstatus_to_exitcode(status)
 if p.returncode:raise RuntimeError((args,Path('child.log').read_text()))
 return dict(arm=arm,threads=threads,fixture=fixture,wall=wall,cpu=r.ru_utime+r.ru_stime,rss_kib=r.ru_maxrss,minor_faults=r.ru_minflt,archive_bytes=out.stat().st_size,archive_sha256=hashlib.sha256(out.read_bytes()).hexdigest())
rows=[]
for fixture in ['zeros']:
 for threads in [2,4]:
  for arm in ['baseline','candidate','7zz']:sample(arm,threads,fixture)
  for run in range(9):
   arms=['baseline','candidate','7zz'];arms=arms[run%3:]+arms[:run%3]
   for arm in arms:
    row=sample(arm,threads,fixture);row['run']=run;rows.append(row)
    Path('samples.json').write_text(json.dumps(rows,indent=2))
  for arm in ['baseline','candidate','7zz']:
   s=[r for r in rows if r['arm']==arm and r['threads']==threads and r['fixture']==fixture]
   print(fixture,threads,arm,{k:statistics.median(r[k] for r in s) for k in ['wall','cpu','rss_kib','minor_faults']},flush=True)
# Verify each encoder's archive with the official decoder and compare output digest.
expected=hashlib.sha256((ROOT/'zeros/data.bin').read_bytes()).hexdigest()
checks=[]
for threads in [2,4]:
 for arm in ['baseline','candidate','7zz']:
  sample(arm,threads,'zeros')
  subprocess.run([str(ROOT/'sevenzip/7zz'),'t',str(ROOT/'out.7z')],check=True,stdout=subprocess.DEVNULL)
  decoded=subprocess.check_output([str(ROOT/'sevenzip/7zz'),'x','-so',str(ROOT/'out.7z')])
  actual=hashlib.sha256(decoded).hexdigest();assert actual==expected
  checks.append(dict(arm=arm,threads=threads,decoded_sha256=actual))
Path('checks.json').write_text(json.dumps(checks,indent=2))
print('archive checks passed',flush=True)

